package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import java.util.Set;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Model;
import org.eclipse.rdf4j.model.util.ModelBuilder;
import org.eclipse.rdf4j.model.util.Values;
import org.eclipse.rdf4j.model.vocabulary.FOAF;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.model.vocabulary.RDFS;
import org.eclipse.rdf4j.query.GraphQuery;
import org.eclipse.rdf4j.query.GraphQueryResult;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class DescribeBindingVerificationTest {

	private final IRI bob = Values.iri("http://example.com/bob");
	private final IRI alice = Values.iri("http://example.com/alice");
	private SailRepository repo;
	private Model data;

	@BeforeEach
	void setUp() {
		repo = new SailRepository(new MemoryStore());
		try (var conn = repo.getConnection()) {
			data = new ModelBuilder()
					.subject(bob)
					.add(RDF.TYPE, FOAF.PERSON)
					.add(RDFS.LABEL, "Bob")
					.subject(alice)
					.add(RDF.TYPE, FOAF.PERSON)
					.add(RDFS.LABEL, "Alice")
					.build();
			conn.add(data);
		}
	}

	@AfterEach
	void tearDown() {
		repo.shutDown();
	}

	@Test
	void testDescribeQuery_MemoryStore() throws Exception {
		try (var conn = repo.getConnection()) {
			GraphQuery gq = conn.prepareGraphQuery(
					"DESCRIBE ?subject WHERE { ?subject <" + RDFS.LABEL.stringValue() + "> ?label }");
			gq.setBinding("label", Values.literal("Alice"));
			try (GraphQueryResult gqr = gq.evaluate()) {
				Model m = QueryResults.asModel(gqr);
				assertEquals(2, m.size());
				assertEquals(Set.of(FOAF.PERSON, Values.literal("Alice")), m.objects());
				assertEquals(data.filter(alice, null, null), m);
			}
		}
	}

	@Test
	void inlineLiteralDescribesAlice() {
		assertEquals(data.filter(alice, null, null), describe("subject", "\"Alice\"", null));
	}

	@Test
	void renamedSubjectWithBindingDescribesAlice() {
		assertEquals(data.filter(alice, null, null), describe("person", "?label", "Alice"));
	}

	@Test
	void noBindingDescribesBothPeople() {
		assertEquals(data, describe("subject", "?label", null));
	}

	@Test
	void unmatchedBindingDescribesNothing() {
		assertEquals(0, describe("subject", "?label", "Carol").size());
	}

	@Test
	void valuesDescribesAlice() {
		try (var conn = repo.getConnection()) {
			var query = conn.prepareGraphQuery("DESCRIBE ?subject WHERE { ?subject <"
					+ RDFS.LABEL.stringValue() + "> ?label VALUES ?label { \"Alice\" } }");
			try (var result = query.evaluate()) {
				assertEquals(data.filter(alice, null, null), QueryResults.asModel(result));
			}
		}
	}

	@Test
	void selectWithSameBindingFindsOnlyAlice() {
		try (var conn = repo.getConnection()) {
			var query = conn.prepareTupleQuery("SELECT ?subject WHERE { ?subject <"
					+ RDFS.LABEL.stringValue() + "> ?label }");
			query.setBinding("label", Values.literal("Alice"));
			try (var result = query.evaluate()) {
				assertEquals(alice, result.next().getValue("subject"));
				assertFalse(result.hasNext());
			}
		}
	}

	private Model describe(String variable, String object, String label) {
		try (var conn = repo.getConnection()) {
			var query = conn.prepareGraphQuery("DESCRIBE ?" + variable + " WHERE { ?" + variable + " <"
					+ RDFS.LABEL.stringValue() + "> " + object + " }");
			if (label != null) {
				query.setBinding("label", Values.literal(label));
			}
			try (var result = query.evaluate()) {
				return QueryResults.asModel(result);
			}
		}
	}
}
